import IMPL_COMPONENT_NAMES from '../../impl-component-names.js';

export function capitalize(word) {
  return word.charAt(0).toUpperCase() + word.slice(1);
}

// "action-button" -> "ActionButton"
export function pascalCase(name) {
  return name.split('-').map(capitalize).join('');
}

// Authored slug -> the real RSP export to import and render. Most agree, so the table
// (generated by deps/build-status-index.js) holds only the divergent minority:
// `action-group` ships as ActionButtonGroup.
//
// `export`, not `docs`: this decides what gets rendered, and a component's docs page is
// often its family's — `takeover-dialog` documents at Dialog but renders
// FullscreenDialog. See buildImplComponentNames in deps/build-status-index.js.
export function resolveRspComponentName(name) {
  const slug = String(name ?? '').trim().toLowerCase();
  return IMPL_COMPONENT_NAMES.rsp?.[slug]?.export ?? pascalCase(slug);
}
